INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d9dedd9-b8ba-513e-8352-aa79f09b9028', 'Albania Labor Code (approved by Law of July 12', 'Labor Code the Republic of Albania (approved by Law No. 7961/1995 of July 12, 1995, and amended up to Law No. 136/2015 of December 5, 2015)', 'The Labor Code of the Republic of Albania, last amended in 2015, outlines regulations for employment contracts, respecting international conventions. It covers temporary employment of foreign workers, working conditions, and exceptions for specific sectors, ensuring legal compliance and protection for both employees and employers in Albania.', 'The Labor Code of the Republic of Albania, last amended in 2015, outlines regulations for employment contracts, respecting international conventions. It covers temporary employment of foreign workers, working conditions, and exceptions for specific sectors, ensuring legal compliance and protection for both employees and employers in Albania.', 'The Labor Code of the Republic of Albania, last amended in 2015, outlines regulations for employment contracts, respecting international conventions. It covers temporary employment of foreign workers, working conditions, and exceptions for specific sectors, ensuring legal compliance and protection for both employees and employers in Albania.', 'Albania', 'social', 'in_force', '2015-01-01'::date, 'Albania', 'https://www.carrotsandsticks.org/policies/2_2', ARRAY['albania', 'sdg8', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46e7e7be-f98e-5ad3-97f0-2e895ddcee6d', 'Corporate Governance Code for Unlisted Joint-Stock Companies in Albania', 'Corporate Governance Code for Unlisted Joint-Stock Companies in Albania, 2008', 'This Corporate Governance Code for Unlisted Joint-Stock Companies in Albania (“the Code”) focuses on specificities of corporate governance for unlisted companies. Most unlisted companies are owned and controlled by a single individual or a coalition of company insiders (e.g., a family). Good governance of unlisted companies is concerned with the establishment of a framework of company processes and attitudes that add value to the business and help ensure long-term continuity and success. This Code is only a best practice reference for unlisted companies in Albania, aimed at designing a framework of best practices being over and above the minimum legal requirements. Thus, it is not a regulation that companies would be obliged to comply with. Also, it is not a soft-law document in relation to which companies will have to report if they comply with or to explain why they do not comply with it (“comply-or-explain” principle). Rather, it is an overview of the best practices in relation to governance of unlisted companies in the moment of its preparation, and it is intended to serve as reference and inspiration for Albanian companies to develop sound governance framework.', 'This Corporate Governance Code for Unlisted Joint-Stock Companies in Albania (“the Code”) focuses on specificities of corporate governance for unlisted companies. Most unlisted companies are owned and controlled by a single individual or a coalition of company insiders (e.g., a family). Good governance of unlisted companies is concerned with the establishment of a framework of company processes and attitudes that add value to the business and help ensure long-term continuity and success. This Code is only a best practice reference for unlisted companies in Albania, aimed at designing a framework of best practices being over and above the minimum legal requirements. Thus, it is not a regulation that companies would be obliged to comply with. Also, it is not a soft-law document in relation to which companies will have to report if they comply with or to explain why they do not comply with it (“comply-or-explain” principle). Rather, it is an overview of the best practices in relation to governance of unlisted companies in the moment of its preparation, and it is intended to serve as reference and inspiration for Albanian companies to develop sound governance framework.', 'This Corporate Governance Code for Unlisted Joint-Stock Companies in Albania (“the Code”) focuses on specificities of corporate governance for unlisted companies. Most unlisted companies are owned and controlled by a single individual or a coalition of company insiders (e.g., a family). Good governance of unlisted companies is concerned with the establishment of a framework of company processes and attitudes that add value to the business and help ensure long-term continuity and success. This Code is only a best practice reference for unlisted companies in Albania, aimed at designing a framework of best practices being over and above the minimum legal requirements. Thus, it is not a regulation that companies would be obliged to comply with. Also, it is not a soft-law document in relation to which companies will have to report if they comply with or to explain why they do not comply with it (“comply-or-explain” principle). Rather, it is an overview of the best practices in relation to governance of unlisted companies in the moment of its preparation, and it is intended to serve as reference and inspiration for Albanian companies to develop sound governance framework.', 'Albania', 'climate', 'in_force', '2008-01-01'::date, 'Albania', 'https://www.carrotsandsticks.org/policies/2_1', ARRAY['regulations', 'sdg7', 'sdg11', 'mandatory', 'albania', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d1072c8b-168e-55c9-b3c5-1bbe04681d0b', 'Algeria MCPD National Action Plan', 'MCPD National Action Plan', 'This action plan sets out Algeria''s commitments under the Minamata Convention, which is a global agreement aimed at reducing the use and release of mercury into the environment. The plan outlines measures to reduce mercury emissions from industrial processes and to phase out the use of mercury in products such as batteries, lamps, and thermometers. It also includes provisions for monitoring and reporting on mercury emissions and for managing mercury-containing waste. The aim of the plan is to protect human health and the environment by reducing exposure to mercury and to contribute to global efforts to address the issue of mercury pollution. This action plan also sets up an incentive system for the publication of voluntary sustainable development reports according to recognized international standards (such as GRI and / or UNGC).', 'This action plan sets out Algeria''s commitments under the Minamata Convention, which is a global agreement aimed at reducing the use and release of mercury into the environment. The plan outlines measures to reduce mercury emissions from industrial processes and to phase out the use of mercury in products such as batteries, lamps, and thermometers. It also includes provisions for monitoring and reporting on mercury emissions and for managing mercury-containing waste. The aim of the plan is to protect human health and the environment by reducing exposure to mercury and to contribute to global efforts to address the issue of mercury pollution. This action plan also sets up an incentive system for the publication of voluntary sustainable development reports according to recognized international standards (such as GRI and / or UNGC).', 'This action plan sets out Algeria''s commitments under the Minamata Convention, which is a global agreement aimed at reducing the use and release of mercury into the environment. The plan outlines measures to reduce mercury emissions from industrial processes and to phase out the use of mercury in products such as batteries, lamps, and thermometers. It also includes provisions for monitoring and reporting on mercury emissions and for managing mercury-containing waste. The aim of the plan is to protect human health and the environment by reducing exposure to mercury and to contribute to global efforts to address the issue of mercury pollution. This action plan also sets up an incentive system for the publication of voluntary sustainable development reports according to recognized international standards (such as GRI and / or UNGC).', 'Algeria', 'climate', 'in_force', '2016-01-01'::date, 'Algeria', 'https://www.carrotsandsticks.org/policies/3_2', ARRAY['sdg13', 'regulations', 'sdg7', 'algeria', 'mandatory', 'sdg6', 'sdg12', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ca356ea-c3da-51d1-b428-01c25e09e769', 'Algerian Corporate Governance Code', 'Algerian Corporate Governance Code', 'The purpose of this Code is to make available to Algerian companies, partially or totally private, a simplified didactic tool allowing them to understand the fundamental principles of corporate governance and to initiate a process, with a view to integrate these principles within them. The proposed Code, while falling within the framework of the laws and regulations in force, has no legal character and does not include any binding provision.', 'The purpose of this Code is to make available to Algerian companies, partially or totally private, a simplified didactic tool allowing them to understand the fundamental principles of corporate governance and to initiate a process, with a view to integrate these principles within them. The proposed Code, while falling within the framework of the laws and regulations in force, has no legal character and does not include any binding provision.', 'The purpose of this Code is to make available to Algerian companies, partially or totally private, a simplified didactic tool allowing them to understand the fundamental principles of corporate governance and to initiate a process, with a view to integrate these principles within them. The proposed Code, while falling within the framework of the laws and regulations in force, has no legal character and does not include any binding provision.', 'Algeria', 'governance', 'in_force', '2009-01-01'::date, 'Algeria', 'https://www.carrotsandsticks.org/policies/3_1', ARRAY['other sustainability policy', 'regulations', 'algeria', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0121f8f-aff4-5e55-a378-1b7cc351f2bc', 'Andorra Law , of January 19, on environmental assessment', 'Law 4/2023, of January 19, on environmental assessment of projects and plans and programs', 'The Andorran policy Law 4/2023 focuses on environmental assessment for projects and plans. Its purpose is to integrate environmental considerations early on, inform stakeholders, and prevent or mitigate environmental impacts. The policy targets project promoters, planners, authorities, and the public, emphasizing prevention, integration, precaution, and citizen participation.', 'The Andorran policy Law 4/2023 focuses on environmental assessment for projects and plans. Its purpose is to integrate environmental considerations early on, inform stakeholders, and prevent or mitigate environmental impacts. The policy targets project promoters, planners, authorities, and the public, emphasizing prevention, integration, precaution, and citizen participation.', 'The Andorran policy Law 4/2023 focuses on environmental assessment for projects and plans. Its purpose is to integrate environmental considerations early on, inform stakeholders, and prevent or mitigate environmental impacts. The policy targets project promoters, planners, authorities, and the public, emphasizing prevention, integration, precaution, and citizen participation.', 'Andorra', 'governance', 'in_force', '2023-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_5', ARRAY['mandatory', 'andorra', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8648d525-ce14-5785-844d-6da94b6c43c1', 'Andorra Law for the development and diversification of the', 'Law 31/2022 for the development and diversification of the livestock and agricultural sectors', 'Andorra''s Law 31/2022 aims to develop and diversify the livestock and agricultural sectors, transitioning from tobacco cultivation. It provides support, incentives, and regulations to ensure sustainable farming practices, enhance product quality, and adapt to changing market demands. Targeted at farmers, ranchers, and stakeholders in Andorra''s agricultural sector.', 'Andorra''s Law 31/2022 aims to develop and diversify the livestock and agricultural sectors, transitioning from tobacco cultivation. It provides support, incentives, and regulations to ensure sustainable farming practices, enhance product quality, and adapt to changing market demands. Targeted at farmers, ranchers, and stakeholders in Andorra''s agricultural sector.', 'Andorra''s Law 31/2022 aims to develop and diversify the livestock and agricultural sectors, transitioning from tobacco cultivation. It provides support, incentives, and regulations to ensure sustainable farming practices, enhance product quality, and adapt to changing market demands. Targeted at farmers, ranchers, and stakeholders in Andorra''s agricultural sector.', 'Andorra', 'climate', 'in_force', '2022-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_6', ARRAY['sdg2', 'mandatory', 'andorra', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('81362c49-a4cf-58f3-acfd-9157afd7ba17', 'Andorra 9-2021 approving the Regulation of the National Greenhouse', 'Decree 303/2021 of 22-9-2021 approving the Regulation of the National Greenhouse Gas Emissions Compensation Market.', 'Andorra''s Decree 303/2021 establishes the Regulation of the National Greenhouse Gas Emissions Compensation Market to achieve ambitious emission reductions. It aims to support economic and social activities, promote environmental responsibility, and facilitate voluntary emissions offset projects. The policy targets individuals, organizations, and businesses in Andorra.', 'Andorra''s Decree 303/2021 establishes the Regulation of the National Greenhouse Gas Emissions Compensation Market to achieve ambitious emission reductions. It aims to support economic and social activities, promote environmental responsibility, and facilitate voluntary emissions offset projects. The policy targets individuals, organizations, and businesses in Andorra.', 'Andorra''s Decree 303/2021 establishes the Regulation of the National Greenhouse Gas Emissions Compensation Market to achieve ambitious emission reductions. It aims to support economic and social activities, promote environmental responsibility, and facilitate voluntary emissions offset projects. The policy targets individuals, organizations, and businesses in Andorra.', 'Andorra', 'climate', 'in_force', '2021-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_7', ARRAY['andorra', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e592368a-696d-5a36-a97f-3f7fe1ed8e2b', 'Andorra 9-2021 approving the Regulation of the national market', 'Decree 303/2021 of 22-9-2021 approving the Regulation of the national market for offsetting greenhouse gas emissions.', 'Andorra''s Decree 303/2021 establishes regulations for a national market to offset greenhouse gas emissions, aligning with its climate goals. The policy aims to support projects that reduce emissions, promote transparency, and encourage a low-carbon economy. It targets individuals, organizations, and businesses interested in voluntary emissions offsetting.', 'Andorra''s Decree 303/2021 establishes regulations for a national market to offset greenhouse gas emissions, aligning with its climate goals. The policy aims to support projects that reduce emissions, promote transparency, and encourage a low-carbon economy. It targets individuals, organizations, and businesses interested in voluntary emissions offsetting.', 'Andorra''s Decree 303/2021 establishes regulations for a national market to offset greenhouse gas emissions, aligning with its climate goals. The policy aims to support projects that reduce emissions, promote transparency, and encourage a low-carbon economy. It targets individuals, organizations, and businesses interested in voluntary emissions offsetting.', 'Andorra', 'climate', 'in_force', '2021-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_8', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'andorra']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6265a42d-a01a-50ea-94a1-790bec132b30', 'Andorra Law , of December 6, qualified as union', 'Law 32/2018, of December 6, qualified as union and employer action.', 'Law 32/2018 in Andorra aims to enhance labor relations and collective bargaining through the recognition of union and employer actions. The policy focuses on promoting democracy within workplaces, fostering dialogue between stakeholders, and advancing social and economic progress through legislative reforms.', 'Law 32/2018 in Andorra aims to enhance labor relations and collective bargaining through the recognition of union and employer actions. The policy focuses on promoting democracy within workplaces, fostering dialogue between stakeholders, and advancing social and economic progress through legislative reforms.', 'Law 32/2018 in Andorra aims to enhance labor relations and collective bargaining through the recognition of union and employer actions. The policy focuses on promoting democracy within workplaces, fostering dialogue between stakeholders, and advancing social and economic progress through legislative reforms.', 'Andorra', 'governance', 'in_force', '2018-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_2', ARRAY['mandatory', 'andorra', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9d6a62c3-52dc-5e6e-86a2-50dea01b3432', 'Andorra Law , of December 6, on labor relations', 'Law 31/2018, of December 6, on labor relations.', 'Law 31/2018 in Andorra governs labor relations, covering contract types, suspension scenarios, employee rights and obligations, salaries, social security, and contract termination. It aims to establish guidelines for labor agreements, protecting workers'' rights, and ensuring fair treatment in the workplace. Targeted at employers, employees, and legal professionals.', 'Law 31/2018 in Andorra governs labor relations, covering contract types, suspension scenarios, employee rights and obligations, salaries, social security, and contract termination. It aims to establish guidelines for labor agreements, protecting workers'' rights, and ensuring fair treatment in the workplace. Targeted at employers, employees, and legal professionals.', 'Law 31/2018 in Andorra governs labor relations, covering contract types, suspension scenarios, employee rights and obligations, salaries, social security, and contract termination. It aims to establish guidelines for labor agreements, protecting workers'' rights, and ensuring fair treatment in the workplace. Targeted at employers, employees, and legal professionals.', 'Andorra', 'social', 'in_force', '2018-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_3', ARRAY['sdg8', 'mandatory', 'andorra', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9cef7401-7a72-58ab-93be-a424ff9f3194', 'Andorra Law , of December 18, on safety', 'Law 34/2008, of December 18, on safety and health at work.', 'Law 34/2008 in Andorra focuses on safety and health at work, outlining general provisions, employer obligations, preventive measures, and worker participation. It aims to protect workers’ health and safety, involving employers, workers, and regulatory bodies to ensure compliance with safety standards.', 'Law 34/2008 in Andorra focuses on safety and health at work, outlining general provisions, employer obligations, preventive measures, and worker participation. It aims to protect workers’ health and safety, involving employers, workers, and regulatory bodies to ensure compliance with safety standards.', 'Law 34/2008 in Andorra focuses on safety and health at work, outlining general provisions, employer obligations, preventive measures, and worker participation. It aims to protect workers’ health and safety, involving employers, workers, and regulatory bodies to ensure compliance with safety standards.', 'Andorra', 'social', 'in_force', '2008-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_1', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg3', 'andorra']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e7ef760-467a-53a0-820c-2fe498177e59', 'Andorra Law , of December 18, entitled Freedom of', 'Law 33/2008, of December 18, entitled Freedom of Association.', 'Law 33/2008 of December 18 in Andorra guarantees freedom of association and outlines regulations for trade unions. It establishes rights and responsibilities of trade union members, registration requirements, and provisions against discrimination. The law aims to protect and promote workers'' interests while ensuring autonomy and legal framework for unions.', 'Law 33/2008 of December 18 in Andorra guarantees freedom of association and outlines regulations for trade unions. It establishes rights and responsibilities of trade union members, registration requirements, and provisions against discrimination. The law aims to protect and promote workers'' interests while ensuring autonomy and legal framework for unions.', 'Law 33/2008 of December 18 in Andorra guarantees freedom of association and outlines regulations for trade unions. It establishes rights and responsibilities of trade union members, registration requirements, and provisions against discrimination. The law aims to protect and promote workers'' interests while ensuring autonomy and legal framework for unions.', 'Andorra', 'social', 'in_force', '2008-01-01'::date, 'Andorra', 'https://www.carrotsandsticks.org/policies/198_4', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'andorra']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8d5fc796-5a0e-5aa8-9595-20d98eaf481f', 'Argentina Corporate Social Responsibility (CSR) Guidelines by Argentine Chamber', 'Corporate Social Responsibility (CSR) Guidelines by Argentine Chamber of Commerce', 'This Guide for the Preparation of Sustainability Reports (2023) offers a structured methodology for SMEs in Argentina to report on their sustainability efforts, focusing on economic, environmental, and social impacts. The guide is aligned with international standards like the Global Reporting Initiative (GRI), United Nations Global Compact (UNGC), and Sustainability Accounting Standards Board (SASB).

The report is designed to help businesses disclose non-financial information, demonstrating accountability and transparency regarding their sustainability practices. It emphasizes aspects like energy consumption, emissions reduction, and ethical business practices, with a particular focus on small and medium-sized enterprises (SMEs) in Argentina. The guide also discusses how companies can meet Sustainable Development Goals (SDGs), specifically SDG 12 (responsible consumption and production), and aligns with global frameworks like the Escazú Agreement.

The document outlines the process, indicators, and structure necessary for the creation of sustainability reports. It also introduces sector-specific indicators for sectors such as textiles and processed foods, with an emphasis on both qualitative and quantitative metrics.', 'This Guide for the Preparation of Sustainability Reports (2023) offers a structured methodology for SMEs in Argentina to report on their sustainability efforts, focusing on economic, environmental, and social impacts. The guide is aligned with international standards like the Global Reporting Initiative (GRI), United Nations Global Compact (UNGC), and Sustainability Accounting Standards Board (SASB).

The report is designed to help businesses disclose non-financial information, demonstrating accountability and transparency regarding their sustainability practices. It emphasizes aspects like energy consumption, emissions reduction, and ethical business practices, with a particular focus on small and medium-sized enterprises (SMEs) in Argentina. The guide also discusses how companies can meet Sustainable Development Goals (SDGs), specifically SDG 12 (responsible consumption and production), and aligns with global frameworks like the Escazú Agreement.

The document outlines the process, indicators, and structure necessary for the creation of sustainability reports. It also introduces sector-specific indicators for sectors such as textiles and processed foods, with an emphasis on both qualitative and quantitative metrics.', 'This Guide for the Preparation of Sustainability Reports (2023) offers a structured methodology for SMEs in Argentina to report on their sustainability efforts, focusing on economic, environmental, and social impacts. The guide is aligned with international standards like the Global Reporting Initiative (GRI), United Nations Global Compact (UNGC), and Sustainability Accounting Standards Board (SASB).

The report is designed to help businesses disclose non-financial information, demonstrating accountability and transparency regarding their sustainability practices. It emphasizes aspects like energy consumption, emissions reduction, and ethical business practices, with a particular focus on small and medium-sized enterprises (SMEs) in Argentina. The guide also discusses how companies can meet Sustainable Development Goals (SDGs), specifically SDG 12 (responsible consumption and production), and aligns with global frameworks like the Escazú Agreement.

The document outlines the process, indicators, and structure necessary for the creation of sustainability reports. It also introduces sector-specific indicators for sectors such as textiles and processed foods, with an emphasis on both qualitative and quantitative metrics.', 'Argentina', 'climate', 'in_force', '2021-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_10', ARRAY['guidance_frameworks', 'sdg13', 'sdg7', 'argentina', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b00321cf-c9bb-5661-a33f-4b4edbcff96e', 'Argentina Buenos Aires Stock Exchange ESG Guidelines (BCBA Guidelines)', 'Buenos Aires Stock Exchange ESG Guidelines (BCBA Guidelines)', 'The BYMA Sustainability Report 2020 highlights the efforts of BYMA (Bolsas y Mercados Argentinos) to integrate sustainability within the Argentine capital markets. The report outlines BYMA''s commitment to environmental, social, and governance (ESG) factors, aligning with global standards such as the UN''s Sustainable Development Goals (SDGs). Key initiatives from 2020 include enhancing market transparency, supporting small and medium-sized enterprises (SMEs) with digital financing solutions, and promoting gender equality through events like the “Toque de Campana” for gender equality. The report also covers BYMA''s technological advancements, including the digitalization of services and the introduction of sustainable investment products such as Social, Green, and Sustainable Bonds (SVS). Additionally, BYMA’s ongoing partnerships with public and private sectors further strengthen its commitment to transparency, risk management, and corporate governance. The report stresses the importance of responsible investment practices and the positive societal impact BYMA aims to achieve through its sustainable market solutions.', 'The BYMA Sustainability Report 2020 highlights the efforts of BYMA (Bolsas y Mercados Argentinos) to integrate sustainability within the Argentine capital markets. The report outlines BYMA''s commitment to environmental, social, and governance (ESG) factors, aligning with global standards such as the UN''s Sustainable Development Goals (SDGs). Key initiatives from 2020 include enhancing market transparency, supporting small and medium-sized enterprises (SMEs) with digital financing solutions, and promoting gender equality through events like the “Toque de Campana” for gender equality. The report also covers BYMA''s technological advancements, including the digitalization of services and the introduction of sustainable investment products such as Social, Green, and Sustainable Bonds (SVS). Additionally, BYMA’s ongoing partnerships with public and private sectors further strengthen its commitment to transparency, risk management, and corporate governance. The report stresses the importance of responsible investment practices and the positive societal impact BYMA aims to achieve through its sustainable market solutions.', 'The BYMA Sustainability Report 2020 highlights the efforts of BYMA (Bolsas y Mercados Argentinos) to integrate sustainability within the Argentine capital markets. The report outlines BYMA''s commitment to environmental, social, and governance (ESG) factors, aligning with global standards such as the UN''s Sustainable Development Goals (SDGs). Key initiatives from 2020 include enhancing market transparency, supporting small and medium-sized enterprises (SMEs) with digital financing solutions, and promoting gender equality through events like the “Toque de Campana” for gender equality. The report also covers BYMA''s technological advancements, including the digitalization of services and the introduction of sustainable investment products such as Social, Green, and Sustainable Bonds (SVS). Additionally, BYMA’s ongoing partnerships with public and private sectors further strengthen its commitment to transparency, risk management, and corporate governance. The report stresses the importance of responsible investment practices and the positive societal impact BYMA aims to achieve through its sustainable market solutions.', 'Argentina', 'climate', 'in_force', '2021-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_4', ARRAY['guidance_frameworks', 'sdg17', 'sdg5', 'argentina', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eba99717-3cae-561c-b414-499274e16654', 'Argentina Financial Inclusion and Sustainable Finance Framework (Reglamento de', 'Financial Inclusion and Sustainable Finance Framework (Reglamento de Finanzas Sostenibles)', 'The Argentina Sustainable Finance National Strategy (ENFS) aims to foster a robust and inclusive financial ecosystem that supports the country’s sustainable development goals (SDGs) and climate commitments under the Paris Agreement. Developed by the Technical Roundtable on Sustainable Finance (MTFS), the strategy outlines five strategic action axes: (1) strengthening the regulatory framework, (2) creating a common language and taxonomy for sustainable finance, (3) improving data generation, transparency, and reporting, (4) designing incentives to stimulate market activity, and (5) promoting sustainable financial instruments.', 'The Argentina Sustainable Finance National Strategy (ENFS) aims to foster a robust and inclusive financial ecosystem that supports the country’s sustainable development goals (SDGs) and climate commitments under the Paris Agreement. Developed by the Technical Roundtable on Sustainable Finance (MTFS), the strategy outlines five strategic action axes: (1) strengthening the regulatory framework, (2) creating a common language and taxonomy for sustainable finance, (3) improving data generation, transparency, and reporting, (4) designing incentives to stimulate market activity, and (5) promoting sustainable financial instruments.', 'The Argentina Sustainable Finance National Strategy (ENFS) aims to foster a robust and inclusive financial ecosystem that supports the country’s sustainable development goals (SDGs) and climate commitments under the Paris Agreement. Developed by the Technical Roundtable on Sustainable Finance (MTFS), the strategy outlines five strategic action axes: (1) strengthening the regulatory framework, (2) creating a common language and taxonomy for sustainable finance, (3) improving data generation, transparency, and reporting, (4) designing incentives to stimulate market activity, and (5) promoting sustainable financial instruments.', 'Argentina', 'climate', 'in_force', '2021-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_5', ARRAY['sdg4', 'sdg13', 'sdg10', 'voluntary', 'argentina', 'sdg16', 'disclosure', 'sdg1', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('53155e3f-a801-57e2-805d-a22f8d864936', 'Argentina Central Bank Climate Change and Sustainability Guideline', 'Central Bank Climate Change and Sustainability Guideline', 'The new regulation introduced by the Central Bank of Brazil (BCB), effective from December 2022, mandates financial institutions to disclose information regarding their management of social, environmental, and climate-related risks. The regulation establishes the GRSAC Report (Governance, Risk, Strategy, and Climate) to provide a structured format for institutions to report on their governance, strategies, and risk management efforts related to these key issues. The regulation follows the Task Force on Climate-related Financial Disclosures (TCFD) recommendations but expands its scope to include social and environmental risks, addressing their potential impacts on business strategies, credit portfolios, and capital management.', 'The new regulation introduced by the Central Bank of Brazil (BCB), effective from December 2022, mandates financial institutions to disclose information regarding their management of social, environmental, and climate-related risks. The regulation establishes the GRSAC Report (Governance, Risk, Strategy, and Climate) to provide a structured format for institutions to report on their governance, strategies, and risk management efforts related to these key issues. The regulation follows the Task Force on Climate-related Financial Disclosures (TCFD) recommendations but expands its scope to include social and environmental risks, addressing their potential impacts on business strategies, credit portfolios, and capital management.', 'The new regulation introduced by the Central Bank of Brazil (BCB), effective from December 2022, mandates financial institutions to disclose information regarding their management of social, environmental, and climate-related risks. The regulation establishes the GRSAC Report (Governance, Risk, Strategy, and Climate) to provide a structured format for institutions to report on their governance, strategies, and risk management efforts related to these key issues. The regulation follows the Task Force on Climate-related Financial Disclosures (TCFD) recommendations but expands its scope to include social and environmental risks, addressing their potential impacts on business strategies, credit portfolios, and capital management.', 'Argentina', 'climate', 'in_force', '2021-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_6', ARRAY['guidance_frameworks', 'sdg13', 'argentina', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('78428f59-2501-5c50-8d1f-c984f5128fff', 'Argentina Corporate Governance Code', 'Corporate Governance Code, 2020', 'The Comisión Nacional de Valores (CNV) Corporate Governance Code 2020 of Argentina is a set of guidelines and best practices designed to promote transparent, efficient, and ethical corporate governance among publicly traded companies in Argentina. The code is intended to provide a framework for companies to improve their management practices, increase accountability and responsibility, and enhance shareholder protection. The code covers a wide range of topics, including board structure and composition, risk management, transparency and disclosure, internal controls, and shareholder rights. It requires companies to establish clear policies and procedures for decision-making, establish independent audit committees, and establish mechanisms for shareholder participation in key decisions. The code also encourages companies to adopt environmental, social, and governance (ESG) practices, including sustainability reporting and engagement with stakeholders. Companies are also encouraged to promote diversity and inclusion on their boards and in their workforce.', 'The Comisión Nacional de Valores (CNV) Corporate Governance Code 2020 of Argentina is a set of guidelines and best practices designed to promote transparent, efficient, and ethical corporate governance among publicly traded companies in Argentina. The code is intended to provide a framework for companies to improve their management practices, increase accountability and responsibility, and enhance shareholder protection. The code covers a wide range of topics, including board structure and composition, risk management, transparency and disclosure, internal controls, and shareholder rights. It requires companies to establish clear policies and procedures for decision-making, establish independent audit committees, and establish mechanisms for shareholder participation in key decisions. The code also encourages companies to adopt environmental, social, and governance (ESG) practices, including sustainability reporting and engagement with stakeholders. Companies are also encouraged to promote diversity and inclusion on their boards and in their workforce.', 'The Comisión Nacional de Valores (CNV) Corporate Governance Code 2020 of Argentina is a set of guidelines and best practices designed to promote transparent, efficient, and ethical corporate governance among publicly traded companies in Argentina. The code is intended to provide a framework for companies to improve their management practices, increase accountability and responsibility, and enhance shareholder protection. The code covers a wide range of topics, including board structure and composition, risk management, transparency and disclosure, internal controls, and shareholder rights. It requires companies to establish clear policies and procedures for decision-making, establish independent audit committees, and establish mechanisms for shareholder participation in key decisions. The code also encourages companies to adopt environmental, social, and governance (ESG) practices, including sustainability reporting and engagement with stakeholders. Companies are also encouraged to promote diversity and inclusion on their boards and in their workforce.', 'Argentina', 'climate', 'in_force', '2020-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_46', ARRAY['sdg10', 'regulations', 'sdg7', 'mandatory', 'argentina', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('29782e07-800a-5f00-a2a8-11dd344ae4a7', 'Argentina Ley de Presupuestos Mínimos de Adaptación y Mitigación', 'Ley 27520 - Ley de Presupuestos Mínimos de Adaptación y Mitigación al Cambio Climático Global', 'The Ley 27520, enacted in Argentina in 2019, establishes the minimum environmental standards for adaptation and mitigation actions regarding climate change. It aims to provide a framework for policies, instruments, and strategies that promote sustainable development while addressing climate change. The law sets principles such as common but differentiated responsibilities, prioritization of vulnerable groups, and the integration of climate change measures across public policies.

Key aspects include:

Creation of the National Climate Change Cabinet (Gabinete Nacional de Cambio Climático) to coordinate intergovernmental efforts.
Development of the National Plan for Adaptation and Mitigation of Climate Change, updated every five years, with strategies for emissions reductions and risk assessment.
A National Climate Information System to ensure transparency and robust tracking of greenhouse gas (GHG) emissions.
Minimum measures for adaptation, including water resource management, disaster risk reduction, and climate-sensitive urban planning.
Minimum measures for mitigation, focusing on renewable energy adoption, energy efficiency, and sustainable agricultural practices.
Public participation and access to environmental information, ensuring that civil society and various stakeholders contribute to policy formulation.
Inter-jurisdictional coordination, ensuring coherence between national, provincial, and municipal efforts.', 'The Ley 27520, enacted in Argentina in 2019, establishes the minimum environmental standards for adaptation and mitigation actions regarding climate change. It aims to provide a framework for policies, instruments, and strategies that promote sustainable development while addressing climate change. The law sets principles such as common but differentiated responsibilities, prioritization of vulnerable groups, and the integration of climate change measures across public policies.

