INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e7fd6e1f-3275-5dfe-b0b3-648797a6428c', 'Argentina Non-Financial Information Disclosure (Ley de Información No Financiera)', 'Non-Financial Information Disclosure (Ley de Información No Financiera)', 'The Ley 11/2018 transposes the European Directive 2014/95/UE into Spanish law, focusing on mandatory non-financial reporting for large companies. It requires specific disclosures on environmental, social, human rights, anti-corruption, and diversity issues. Affected businesses must provide an annual Non-Financial Information Statement (EINF), including performance indicators on sustainability matters, such as climate impact. The law stresses the importance of transparency to improve corporate accountability, public trust, and long-term sustainability. It applies to large companies exceeding set thresholds (e.g., 500 employees, €40 million in annual turnover). The EINF must be prepared in accordance with specific EU guidelines, including those on climate-related information. The law also discusses verification by independent auditors and details the responsibilities of company boards to ensure accuracy and transparency in the disclosures.', 'The Ley 11/2018 transposes the European Directive 2014/95/UE into Spanish law, focusing on mandatory non-financial reporting for large companies. It requires specific disclosures on environmental, social, human rights, anti-corruption, and diversity issues. Affected businesses must provide an annual Non-Financial Information Statement (EINF), including performance indicators on sustainability matters, such as climate impact. The law stresses the importance of transparency to improve corporate accountability, public trust, and long-term sustainability. It applies to large companies exceeding set thresholds (e.g., 500 employees, €40 million in annual turnover). The EINF must be prepared in accordance with specific EU guidelines, including those on climate-related information. The law also discusses verification by independent auditors and details the responsibilities of company boards to ensure accuracy and transparency in the disclosures.', 'The Ley 11/2018 transposes the European Directive 2014/95/UE into Spanish law, focusing on mandatory non-financial reporting for large companies. It requires specific disclosures on environmental, social, human rights, anti-corruption, and diversity issues. Affected businesses must provide an annual Non-Financial Information Statement (EINF), including performance indicators on sustainability matters, such as climate impact. The law stresses the importance of transparency to improve corporate accountability, public trust, and long-term sustainability. It applies to large companies exceeding set thresholds (e.g., 500 employees, €40 million in annual turnover). The EINF must be prepared in accordance with specific EU guidelines, including those on climate-related information. The law also discusses verification by independent auditors and details the responsibilities of company boards to ensure accuracy and transparency in the disclosures.', 'Argentina', 'climate', 'in_force', '2018-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_2', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'argentina', 'sdg16', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0a360c88-fd2d-5995-9536-22c22517991c', 'Argentina First national action plan on human rights', 'First national action plan on human rights (2017-2020)', 'The thematic axes addressed by the National Action Plan on Human Rights,  are: Inclusion, non-discrimination and equality; Public safety and non-violence; Memory, truth, justice and reparation policies; Universal access to rights; Civic culture and commitment to human rights.', 'The thematic axes addressed by the National Action Plan on Human Rights,  are: Inclusion, non-discrimination and equality; Public safety and non-violence; Memory, truth, justice and reparation policies; Universal access to rights; Civic culture and commitment to human rights.', 'The thematic axes addressed by the National Action Plan on Human Rights,  are: Inclusion, non-discrimination and equality; Public safety and non-violence; Memory, truth, justice and reparation policies; Universal access to rights; Civic culture and commitment to human rights.', 'Argentina', 'social', 'in_force', '2017-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_11', ARRAY['other sustainability policy', 'sdg10', 'regulations', 'mandatory', 'argentina', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3b3a830-3884-51f2-b636-acb681425057', 'Argentina Bill S', 'Bill S-3811/15', 'The law seeks to establish a minimum legal framework for Corporate Social Responsibility in Argentina. The law looks at increasing companies’ capacity for becoming more socially responsible. It also seeks to target SMEs in this process and create an ''accreditation'' program for Socially Responsible Enterprises.', 'The law seeks to establish a minimum legal framework for Corporate Social Responsibility in Argentina. The law looks at increasing companies’ capacity for becoming more socially responsible. It also seeks to target SMEs in this process and create an ''accreditation'' program for Socially Responsible Enterprises.', 'The law seeks to establish a minimum legal framework for Corporate Social Responsibility in Argentina. The law looks at increasing companies’ capacity for becoming more socially responsible. It also seeks to target SMEs in this process and create an ''accreditation'' program for Socially Responsible Enterprises.', 'Argentina', 'governance', 'in_force', '2015-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_12', ARRAY['argentina', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4422126f-4845-52b2-b5bf-c8c17bea1769', 'Argentina Bill S', 'Bill S-0765/12', 'The purpose of this law is to establish the legal framework for the preparation of the sustainability report to which companies operating in the territory of the Republic under any modality must adhere. Likewise, the purpose of this is to regulate the exposure of the social, environmental, and good governance results of companies with their stakeholders.', 'The purpose of this law is to establish the legal framework for the preparation of the sustainability report to which companies operating in the territory of the Republic under any modality must adhere. Likewise, the purpose of this is to regulate the exposure of the social, environmental, and good governance results of companies with their stakeholders.', 'The purpose of this law is to establish the legal framework for the preparation of the sustainability report to which companies operating in the territory of the Republic under any modality must adhere. Likewise, the purpose of this is to regulate the exposure of the social, environmental, and good governance results of companies with their stakeholders.', 'Argentina', 'climate', 'in_force', '2014-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_9', ARRAY['regulations', 'sdg11', 'mandatory', 'argentina', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec7358e6-718f-5833-8205-c57834c2cedb', 'Argentina General Resolution - Standards N.T', 'General Resolution 622/2013 - Standards N.T. 2013', 'Resolución General 622/2013 in Argentina establishes the Normas N.T. 2013, which are the technical standards for digital tax records and documentation. The resolution places obligations on businesses to adopt electronic invoicing and other digital records and documentation practices. Businesses must comply with the technical requirements of the Normas N.T. 2013, which includes the use of digital signatures, digital certificates, and other security measures to ensure the authenticity, integrity, and confidentiality of electronic records. The resolution also establishes penalties for non-compliance with the regulations, including fines and the potential suspension of the taxpayer''s ability to use electronic invoicing. In summary, Resolución General 622/2013 places significant obligations on businesses in Argentina to adopt electronic invoicing and other digital records practices in compliance with the Normas N.T. 2013.', 'Resolución General 622/2013 in Argentina establishes the Normas N.T. 2013, which are the technical standards for digital tax records and documentation. The resolution places obligations on businesses to adopt electronic invoicing and other digital records and documentation practices. Businesses must comply with the technical requirements of the Normas N.T. 2013, which includes the use of digital signatures, digital certificates, and other security measures to ensure the authenticity, integrity, and confidentiality of electronic records. The resolution also establishes penalties for non-compliance with the regulations, including fines and the potential suspension of the taxpayer''s ability to use electronic invoicing. In summary, Resolución General 622/2013 places significant obligations on businesses in Argentina to adopt electronic invoicing and other digital records practices in compliance with the Normas N.T. 2013.', 'Resolución General 622/2013 in Argentina establishes the Normas N.T. 2013, which are the technical standards for digital tax records and documentation. The resolution places obligations on businesses to adopt electronic invoicing and other digital records and documentation practices. Businesses must comply with the technical requirements of the Normas N.T. 2013, which includes the use of digital signatures, digital certificates, and other security measures to ensure the authenticity, integrity, and confidentiality of electronic records. The resolution also establishes penalties for non-compliance with the regulations, including fines and the potential suspension of the taxpayer''s ability to use electronic invoicing. In summary, Resolución General 622/2013 places significant obligations on businesses in Argentina to adopt electronic invoicing and other digital records practices in compliance with the Normas N.T. 2013.', 'Argentina', 'nature', 'in_force', '2013-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_41', ARRAY['other sustainability policy', 'voluntary', 'argentina', 'sdg16', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('423e401f-7300-5e43-a7c7-821a26db8ea2', 'Argentina Bill 7201- D/13', 'Bill 7201- D/13, 2013', 'This bill encourages socially responsible conducts and guarantees public access to companies’ environmental and social information. It lays out voluntary mandates for CSR, socio-environmental balance, measures of development/promotion/protection and publicity of socially responsible conducts, tax benefits, minimum state budget for public policies for CSR.', 'This bill encourages socially responsible conducts and guarantees public access to companies’ environmental and social information. It lays out voluntary mandates for CSR, socio-environmental balance, measures of development/promotion/protection and publicity of socially responsible conducts, tax benefits, minimum state budget for public policies for CSR.', 'This bill encourages socially responsible conducts and guarantees public access to companies’ environmental and social information. It lays out voluntary mandates for CSR, socio-environmental balance, measures of development/promotion/protection and publicity of socially responsible conducts, tax benefits, minimum state budget for public policies for CSR.', 'Argentina', 'climate', 'in_force', '2013-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_8', ARRAY['sdg13', 'mandatory', 'argentina', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('070db1c1-207c-5cea-ad2c-a365dbf97981', 'Argentina General Resolution Corporate Governance Code', 'General Resolution 606/2012 Corporate Governance Code', 'The purpose of this law is to set the minimum legal framework for corporate social responsibility in Argentina.', 'The purpose of this law is to set the minimum legal framework for corporate social responsibility in Argentina.', 'The purpose of this law is to set the minimum legal framework for corporate social responsibility in Argentina.', 'Argentina', 'governance', 'in_force', '2012-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_13', ARRAY['regulations', 'mandatory', 'argentina', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00f006c9-80ec-5f33-849f-d6c1aef8e737', 'Argentina Corporate Social Responsibility (CSR) Law', 'Corporate Social Responsibility (CSR) Law, No. 8488', 'The purpose of this Law is to promote the socially responsible behaviour of companies and organizations in general, in the design and materialization of their policies, in order to achieve an objective assessment and evaluation of social, environmental, economic and financial sustainability. To this end, the legal framework of the Balance of Corporate Social and Environmental Responsibility (BRSAE) is established.', 'The purpose of this Law is to promote the socially responsible behaviour of companies and organizations in general, in the design and materialization of their policies, in order to achieve an objective assessment and evaluation of social, environmental, economic and financial sustainability. To this end, the legal framework of the Balance of Corporate Social and Environmental Responsibility (BRSAE) is established.', 'The purpose of this Law is to promote the socially responsible behaviour of companies and organizations in general, in the design and materialization of their policies, in order to achieve an objective assessment and evaluation of social, environmental, economic and financial sustainability. To this end, the legal framework of the Balance of Corporate Social and Environmental Responsibility (BRSAE) is established.', 'Argentina', 'climate', 'in_force', '2012-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_15', ARRAY['sdg13', 'regulations', 'mandatory', 'argentina', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca0fe5ea-2d87-581f-9208-9b5ce183f5f9', 'Argentina Securities Market Law (Ley del Mercado de Valores)', 'Securities Market Law (Ley del Mercado de Valores)', 'The Ley del Mercado de Valores regulates the securities market in Mexico to ensure transparency, fairness, and efficiency. The law aims to protect investors, minimize systemic risk, and promote healthy market competition. It applies to companies engaging in securities issuance, trading, and market activities, including publicly listed firms. Key provisions of the law cover the registration and disclosure of securities, requirements for public offerings, and corporate governance practices for listed companies. The law also mandates that companies disclose material information about financial performance, risks, and operations to enable informed investment decisions.

Furthermore, the law emphasizes corporate responsibility, requiring entities involved in securities to follow clear, consistent, and transparent reporting practices, especially in their financial statements, risk disclosures, and governance practices. It also includes provisions for independent audits and specific committees to oversee compliance and performance.', 'The Ley del Mercado de Valores regulates the securities market in Mexico to ensure transparency, fairness, and efficiency. The law aims to protect investors, minimize systemic risk, and promote healthy market competition. It applies to companies engaging in securities issuance, trading, and market activities, including publicly listed firms. Key provisions of the law cover the registration and disclosure of securities, requirements for public offerings, and corporate governance practices for listed companies. The law also mandates that companies disclose material information about financial performance, risks, and operations to enable informed investment decisions.

Furthermore, the law emphasizes corporate responsibility, requiring entities involved in securities to follow clear, consistent, and transparent reporting practices, especially in their financial statements, risk disclosures, and governance practices. It also includes provisions for independent audits and specific committees to oversee compliance and performance.', 'The Ley del Mercado de Valores regulates the securities market in Mexico to ensure transparency, fairness, and efficiency. The law aims to protect investors, minimize systemic risk, and promote healthy market competition. It applies to companies engaging in securities issuance, trading, and market activities, including publicly listed firms. Key provisions of the law cover the registration and disclosure of securities, requirements for public offerings, and corporate governance practices for listed companies. The law also mandates that companies disclose material information about financial performance, risks, and operations to enable informed investment decisions.

Furthermore, the law emphasizes corporate responsibility, requiring entities involved in securities to follow clear, consistent, and transparent reporting practices, especially in their financial statements, risk disclosures, and governance practices. It also includes provisions for independent audits and specific committees to oversee compliance and performance.', 'Argentina', 'climate', 'in_force', '2012-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_3', ARRAY['sdg8', 'regulations', 'sdg11', 'mandatory', 'argentina', 'sdg16', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('778a1c77-8df1-58f7-a663-b31962d78394', 'Argentina Procedures for the measurement and registration of emissions', 'Resolution 13/2012 - Procedures for the measurement and registration of emissions to the atmosphere', 'This regulation establishes procedures for measuring and recording atmospheric emissions from industrial sources. It aims to control and reduce air pollution by requiring companies to monitor and report their emissions in a standardized and transparent manner. Under the regulation, companies are required to measure their emissions using approved methods and equipment. The measurements must be recorded in a transparent manner and reported to the relevant authorities on a regular basis. The regulation also sets limits on the amount of emissions allowed, based on the type of industry and the pollutants being emitted. The regulation requires companies to develop and implement an environmental management plan to reduce their emissions over time. The plan should include specific measures to reduce emissions, such as the use of cleaner production processes or the installation of pollution control equipment. The authorities responsible for enforcing the regulation have the power to conduct inspections and audits to ensure compliance. Companies found to be in violation of the regulation may face fines or other penalties.', 'This regulation establishes procedures for measuring and recording atmospheric emissions from industrial sources. It aims to control and reduce air pollution by requiring companies to monitor and report their emissions in a standardized and transparent manner. Under the regulation, companies are required to measure their emissions using approved methods and equipment. The measurements must be recorded in a transparent manner and reported to the relevant authorities on a regular basis. The regulation also sets limits on the amount of emissions allowed, based on the type of industry and the pollutants being emitted. The regulation requires companies to develop and implement an environmental management plan to reduce their emissions over time. The plan should include specific measures to reduce emissions, such as the use of cleaner production processes or the installation of pollution control equipment. The authorities responsible for enforcing the regulation have the power to conduct inspections and audits to ensure compliance. Companies found to be in violation of the regulation may face fines or other penalties.', 'This regulation establishes procedures for measuring and recording atmospheric emissions from industrial sources. It aims to control and reduce air pollution by requiring companies to monitor and report their emissions in a standardized and transparent manner. Under the regulation, companies are required to measure their emissions using approved methods and equipment. The measurements must be recorded in a transparent manner and reported to the relevant authorities on a regular basis. The regulation also sets limits on the amount of emissions allowed, based on the type of industry and the pollutants being emitted. The regulation requires companies to develop and implement an environmental management plan to reduce their emissions over time. The plan should include specific measures to reduce emissions, such as the use of cleaner production processes or the installation of pollution control equipment. The authorities responsible for enforcing the regulation have the power to conduct inspections and audits to ensure compliance. Companies found to be in violation of the regulation may face fines or other penalties.', 'Argentina', 'climate', 'in_force', '2012-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_37', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg7', 'mandatory', 'argentina', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('82b56a0c-e5b0-5911-a4dc-9098ac9de0e9', 'Argentina Law 26.639 - Environment', 'Law 26.639 - Environment', 'This law establishes the minimum budgets for the protection of glaciers and the periglacial environment in order to preserve them as strategic reserves of water resources for human consumption; for agriculture and as providers of water for the recharge of hydrographic basins; for the protection of biodiversity; as a source of scientific information and as a tourist attraction. Glaciers constitute public goods.', 'This law establishes the minimum budgets for the protection of glaciers and the periglacial environment in order to preserve them as strategic reserves of water resources for human consumption; for agriculture and as providers of water for the recharge of hydrographic basins; for the protection of biodiversity; as a source of scientific information and as a tourist attraction. Glaciers constitute public goods.', 'This law establishes the minimum budgets for the protection of glaciers and the periglacial environment in order to preserve them as strategic reserves of water resources for human consumption; for agriculture and as providers of water for the recharge of hydrographic basins; for the protection of biodiversity; as a source of scientific information and as a tourist attraction. Glaciers constitute public goods.', 'Argentina', 'climate', 'in_force', '2010-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_33', ARRAY['sdg2', 'sdg13', 'sdg14', 'other sustainability policy', 'regulations', 'sdg9', 'mandatory', 'sdg6', 'argentina', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb10575b-facb-5d2a-a540-5ded0e291634', 'Argentina Resolution - Natural Gas', 'Resolution 609/2009 - Natural Gas', 'Resolution 609/2009 was issued in Argentina to regulate the use, production, transportation, and distribution of natural gas. The resolution establishes the obligations of businesses involved in the natural gas industry, including the obligation to comply with safety and environmental standards during the exploration, production, and transportation of natural gas. Businesses are required to obtain licenses from regulatory authorities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 609/2009 places significant obligations on businesses in the natural gas industry in Argentina, with the aim of ensuring the safe and sustainable use of natural gas resources.', 'Resolution 609/2009 was issued in Argentina to regulate the use, production, transportation, and distribution of natural gas. The resolution establishes the obligations of businesses involved in the natural gas industry, including the obligation to comply with safety and environmental standards during the exploration, production, and transportation of natural gas. Businesses are required to obtain licenses from regulatory authorities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 609/2009 places significant obligations on businesses in the natural gas industry in Argentina, with the aim of ensuring the safe and sustainable use of natural gas resources.', 'Resolution 609/2009 was issued in Argentina to regulate the use, production, transportation, and distribution of natural gas. The resolution establishes the obligations of businesses involved in the natural gas industry, including the obligation to comply with safety and environmental standards during the exploration, production, and transportation of natural gas. Businesses are required to obtain licenses from regulatory authorities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 609/2009 places significant obligations on businesses in the natural gas industry in Argentina, with the aim of ensuring the safe and sustainable use of natural gas resources.', 'Argentina', 'climate', 'in_force', '2009-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_40', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'argentina', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4446fab3-ee25-5678-a40f-36ac0de12e38', 'Argentina Industrial Reconversion Programs', 'Resolution 1139/2008 - Industrial Reconversion Programs', 'This resolution is a program created by the Argentine government to promote the modernization and reconversion of industrial sectors facing economic difficulties. The program aims to support companies in their efforts to improve their competitiveness, reduce production costs, and increase their level of innovation. To be eligible for the program, companies must submit a proposal that outlines their plans for modernization and reconversion. The proposal should detail the investments required, the expected outcomes, and the impact on employment levels. The government will evaluate the proposal based on its potential to create jobs, increase exports, and generate value-added activities. Companies that are approved for the program can receive financial assistance in the form of non-reimbursable contributions or low-interest loans. The financial support can be used to cover a range of expenses, including the purchase of machinery and equipment, the development of new products, and the training of employees. In addition to the financial assistance, companies that participate in the program will receive technical support and guidance from the government to ensure the success of their modernization and reconversion efforts. The government will also monitor the progress of the program and evaluate its impact on the industrial sector.', 'This resolution is a program created by the Argentine government to promote the modernization and reconversion of industrial sectors facing economic difficulties. The program aims to support companies in their efforts to improve their competitiveness, reduce production costs, and increase their level of innovation. To be eligible for the program, companies must submit a proposal that outlines their plans for modernization and reconversion. The proposal should detail the investments required, the expected outcomes, and the impact on employment levels. The government will evaluate the proposal based on its potential to create jobs, increase exports, and generate value-added activities. Companies that are approved for the program can receive financial assistance in the form of non-reimbursable contributions or low-interest loans. The financial support can be used to cover a range of expenses, including the purchase of machinery and equipment, the development of new products, and the training of employees. In addition to the financial assistance, companies that participate in the program will receive technical support and guidance from the government to ensure the success of their modernization and reconversion efforts. The government will also monitor the progress of the program and evaluate its impact on the industrial sector.', 'This resolution is a program created by the Argentine government to promote the modernization and reconversion of industrial sectors facing economic difficulties. The program aims to support companies in their efforts to improve their competitiveness, reduce production costs, and increase their level of innovation. To be eligible for the program, companies must submit a proposal that outlines their plans for modernization and reconversion. The proposal should detail the investments required, the expected outcomes, and the impact on employment levels. The government will evaluate the proposal based on its potential to create jobs, increase exports, and generate value-added activities. Companies that are approved for the program can receive financial assistance in the form of non-reimbursable contributions or low-interest loans. The financial support can be used to cover a range of expenses, including the purchase of machinery and equipment, the development of new products, and the training of employees. In addition to the financial assistance, companies that participate in the program will receive technical support and guidance from the government to ensure the success of their modernization and reconversion efforts. The government will also monitor the progress of the program and evaluate its impact on the industrial sector.', 'Argentina', 'climate', 'in_force', '2008-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_34', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e580755-f7cd-547c-9b5e-226f0567f190', 'Argentina Minimum budgets for environmental protection of native forests', 'Law 26.331 - Minimum budgets for environmental protection of native forests', 'This law establishes the minimum budgets for environmental protection for the enrichment, restoration, conservation, use and sustainable management of native forests, and the environmental services they provide to society. Likewise, it establishes a promotion regime and criteria for the distribution of funds for the environmental services provided by native forests.', 'This law establishes the minimum budgets for environmental protection for the enrichment, restoration, conservation, use and sustainable management of native forests, and the environmental services they provide to society. Likewise, it establishes a promotion regime and criteria for the distribution of funds for the environmental services provided by native forests.', 'This law establishes the minimum budgets for environmental protection for the enrichment, restoration, conservation, use and sustainable management of native forests, and the environmental services they provide to society. Likewise, it establishes a promotion regime and criteria for the distribution of funds for the environmental services provided by native forests.', 'Argentina', 'nature', 'in_force', '2007-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_32', ARRAY['sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('21591bf6-71eb-57cf-b1d8-802abb0cd5bc', 'Argentina Resolution - Hydrocarbons', 'Resolution 785/2005 - Hydrocarbons', 'This resolution establishes guidelines for the exploration and exploitation of hydrocarbon resources in the country. It sets out requirements for obtaining exploration and exploitation permits, including provisions for environmental impact assessments and the development of contingency plans to manage potential environmental risks. The resolution also establishes rules for the allocation of hydrocarbon resources and the distribution of revenues from their exploitation. The aim of the resolution is to promote the sustainable development of Argentina''s hydrocarbon resources while also ensuring that environmental risks are adequately managed and the benefits of their exploitation are shared fairly.', 'This resolution establishes guidelines for the exploration and exploitation of hydrocarbon resources in the country. It sets out requirements for obtaining exploration and exploitation permits, including provisions for environmental impact assessments and the development of contingency plans to manage potential environmental risks. The resolution also establishes rules for the allocation of hydrocarbon resources and the distribution of revenues from their exploitation. The aim of the resolution is to promote the sustainable development of Argentina''s hydrocarbon resources while also ensuring that environmental risks are adequately managed and the benefits of their exploitation are shared fairly.', 'This resolution establishes guidelines for the exploration and exploitation of hydrocarbon resources in the country. It sets out requirements for obtaining exploration and exploitation permits, including provisions for environmental impact assessments and the development of contingency plans to manage potential environmental risks. The resolution also establishes rules for the allocation of hydrocarbon resources and the distribution of revenues from their exploitation. The aim of the resolution is to promote the sustainable development of Argentina''s hydrocarbon resources while also ensuring that environmental risks are adequately managed and the benefits of their exploitation are shared fairly.', 'Argentina', 'climate', 'in_force', '2005-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_43', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'argentina']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bfa2fbb2-b7c6-5ea8-be9a-47537b6bfa13', 'Argentina Code of Best Governance Practices of Organizations', 'Code of Best Governance Practices of Organizations for the Argentine Republic', 'The Code of Best Corporate Governance Practices for the Argentine Republic provides guidelines for the best management and control of companies, aimed at increasing their value.', 'The Code of Best Corporate Governance Practices for the Argentine Republic provides guidelines for the best management and control of companies, aimed at increasing their value.', 'The Code of Best Corporate Governance Practices for the Argentine Republic provides guidelines for the best management and control of companies, aimed at increasing their value.', 'Argentina', 'governance', 'in_force', '2004-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_14', ARRAY['regulations', 'mandatory', 'argentina', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('123b11a6-770a-549c-86b2-f7b27e627865', 'Argentina Substances that deplete the ozone layer', 'Resolution 953/2004 - Substances that deplete the ozone layer', 'In 2004, Argentina issued "Resolución 953/2004 - Sustancias que agotan la capa de ozono" or Resolution 953/2004 - Ozone Depleting Substances. This resolution established regulations for the import, export, production, and consumption of ozone-depleting substances in Argentina. It also established requirements for the safe handling, storage, and disposal of these substances, as well as the training and certification of individuals involved in their use. The aim of the resolution was to reduce the consumption and production of ozone-depleting substances in Argentina and to promote the use of alternatives that are less harmful to the environment. This was in line with Argentina''s commitment to the Montreal Protocol, an international agreement aimed at protecting the ozone layer. Under this resolution. companies have specific obligations related to the import, export, production, and consumption of ozone-depleting substances, including: (1) Obtaining the necessary permits and licenses for the import, export, and production of ozone-depleting substances; (2) Keeping records and documentation related to the use, storage, and disposal of these substances; (3) Ensuring that their handling and disposal of these substances comply with the legal requirements and do not pose a risk to the environment or public health; (4)  Providing training to their employees who handle these substances. Reporting their import, export, and production of these substances to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible use of ozone-depleting substances in Argentina, while minimizing the risks to human health and the environment.', 'In 2004, Argentina issued "Resolución 953/2004 - Sustancias que agotan la capa de ozono" or Resolution 953/2004 - Ozone Depleting Substances. This resolution established regulations for the import, export, production, and consumption of ozone-depleting substances in Argentina. It also established requirements for the safe handling, storage, and disposal of these substances, as well as the training and certification of individuals involved in their use. The aim of the resolution was to reduce the consumption and production of ozone-depleting substances in Argentina and to promote the use of alternatives that are less harmful to the environment. This was in line with Argentina''s commitment to the Montreal Protocol, an international agreement aimed at protecting the ozone layer. Under this resolution. companies have specific obligations related to the import, export, production, and consumption of ozone-depleting substances, including: (1) Obtaining the necessary permits and licenses for the import, export, and production of ozone-depleting substances; (2) Keeping records and documentation related to the use, storage, and disposal of these substances; (3) Ensuring that their handling and disposal of these substances comply with the legal requirements and do not pose a risk to the environment or public health; (4)  Providing training to their employees who handle these substances. Reporting their import, export, and production of these substances to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible use of ozone-depleting substances in Argentina, while minimizing the risks to human health and the environment.', 'In 2004, Argentina issued "Resolución 953/2004 - Sustancias que agotan la capa de ozono" or Resolution 953/2004 - Ozone Depleting Substances. This resolution established regulations for the import, export, production, and consumption of ozone-depleting substances in Argentina. It also established requirements for the safe handling, storage, and disposal of these substances, as well as the training and certification of individuals involved in their use. The aim of the resolution was to reduce the consumption and production of ozone-depleting substances in Argentina and to promote the use of alternatives that are less harmful to the environment. This was in line with Argentina''s commitment to the Montreal Protocol, an international agreement aimed at protecting the ozone layer. Under this resolution. companies have specific obligations related to the import, export, production, and consumption of ozone-depleting substances, including: (1) Obtaining the necessary permits and licenses for the import, export, and production of ozone-depleting substances; (2) Keeping records and documentation related to the use, storage, and disposal of these substances; (3) Ensuring that their handling and disposal of these substances comply with the legal requirements and do not pose a risk to the environment or public health; (4)  Providing training to their employees who handle these substances. Reporting their import, export, and production of these substances to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible use of ozone-depleting substances in Argentina, while minimizing the risks to human health and the environment.', 'Argentina', 'climate', 'in_force', '2004-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_45', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9157f3a1-7df9-5dc8-ad35-e5dc9b1ed5c1', 'Argentina Decree Access to Public Information. General Regulations', 'Decree 1172/2003 Access to Public Information. General Regulations', 'This decree approves the General Regulations of Public Hearings for the National Executive Power, for the Publicity of the Management of Interests in the scope of the National Executive Power, for the Participative Elaboration of Norms, of Access to Information Public for the National Executive Power and Open Meetings of the Regulatory Entities of Public Services, Registration forms, registration and presentation of opinions and proposals. Free and open access via the Internet to the daily edition of the Official Gazette of the Argentine Republic is established. This decree is applicable to public hearings convened in the sphere of agencies, entities, companies, companies, dependencies, and any other entity that functions under the jurisdiction of the National Executive Power.', 'This decree approves the General Regulations of Public Hearings for the National Executive Power, for the Publicity of the Management of Interests in the scope of the National Executive Power, for the Participative Elaboration of Norms, of Access to Information Public for the National Executive Power and Open Meetings of the Regulatory Entities of Public Services, Registration forms, registration and presentation of opinions and proposals. Free and open access via the Internet to the daily edition of the Official Gazette of the Argentine Republic is established. This decree is applicable to public hearings convened in the sphere of agencies, entities, companies, companies, dependencies, and any other entity that functions under the jurisdiction of the National Executive Power.', 'This decree approves the General Regulations of Public Hearings for the National Executive Power, for the Publicity of the Management of Interests in the scope of the National Executive Power, for the Participative Elaboration of Norms, of Access to Information Public for the National Executive Power and Open Meetings of the Regulatory Entities of Public Services, Registration forms, registration and presentation of opinions and proposals. Free and open access via the Internet to the daily edition of the Official Gazette of the Argentine Republic is established. This decree is applicable to public hearings convened in the sphere of agencies, entities, companies, companies, dependencies, and any other entity that functions under the jurisdiction of the National Executive Power.', 'Argentina', 'governance', 'in_force', '2003-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_19', ARRAY['argentina', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6c84067-a022-5019-aba2-f8f2a80c6faf', 'Argentina Resolution - Occupational Hazards', 'Resolution 743/2003 - Occupational Hazards', 'Provides for the operation of the "national registry for the prevention of major industrial accidents". Updates the list of chemical substances in annex I of the DNSST provision nº 8/95.', 'Provides for the operation of the "national registry for the prevention of major industrial accidents". Updates the list of chemical substances in annex I of the DNSST provision nº 8/95.', 'Provides for the operation of the "national registry for the prevention of major industrial accidents". Updates the list of chemical substances in annex I of the DNSST provision nº 8/95.', 'Argentina', 'social', 'in_force', '2003-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_42', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'argentina', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f6feacb-4936-5e42-aab6-99ec8f72107b', 'Argentina Minimum budgets for the management and disposal of', 'Law 25.670 - Minimum budgets for the management and disposal of PCBs', 'This standard establishes the minimum budgets for environmental protection for the management of PCBs, throughout the Nation''s territory. The purpose of this is: a) Supervise the operations associated with PCBs; b) The decontamination or disposal of equipment containing PCBs; c) The disposal of used PCBs; d) The prohibition of entry into the country of PCBs; e) The prohibition of production and commercialization of PCBs.', 'This standard establishes the minimum budgets for environmental protection for the management of PCBs, throughout the Nation''s territory. The purpose of this is: a) Supervise the operations associated with PCBs; b) The decontamination or disposal of equipment containing PCBs; c) The disposal of used PCBs; d) The prohibition of entry into the country of PCBs; e) The prohibition of production and commercialization of PCBs.', 'This standard establishes the minimum budgets for environmental protection for the management of PCBs, throughout the Nation''s territory. The purpose of this is: a) Supervise the operations associated with PCBs; b) The decontamination or disposal of equipment containing PCBs; c) The disposal of used PCBs; d) The prohibition of entry into the country of PCBs; e) The prohibition of production and commercialization of PCBs.', 'Argentina', 'circularity', 'in_force', '2002-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_25', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bb3e67b-f15a-5892-a3bd-2800c98a3264', 'Argentina National environmental policy', 'Law 25.675 - National environmental policy', 'The law establishes the minimum budgets for the achievement of sustainable and adequate management of the environment, the preservation and protection of biological diversity and the implementation of sustainable development in Argentina.', 'The law establishes the minimum budgets for the achievement of sustainable and adequate management of the environment, the preservation and protection of biological diversity and the implementation of sustainable development in Argentina.', 'The law establishes the minimum budgets for the achievement of sustainable and adequate management of the environment, the preservation and protection of biological diversity and the implementation of sustainable development in Argentina.', 'Argentina', 'nature', 'in_force', '2002-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_30', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8779e07b-4e20-5ecd-9ec2-407868093579', 'Argentina Waste or Non-Hazardous Waste', 'Resolution 946/2002 - Waste or Non-Hazardous Waste', 'This resolution sets out guidelines for the management and disposal of non-hazardous waste in Argentina. It establishes criteria for the classification of waste and provides guidelines for the storage, transportation, and disposal of non-hazardous waste. The resolution also includes provisions for the monitoring and reporting of waste management activities. Under this resolution companies have specific obligations related to the management and disposal of non-hazardous waste, including: (1) Properly classifying their waste according to the guidelines established in the resolution; (2) Storing and transporting their waste in a manner that prevents environmental contamination and protects human health; (3) Ensuring that their waste disposal methods comply with the legal requirements and do not pose a risk to the environment or public health; (4) Maintaining records and documentation related to their waste management activities, including the volume and type of waste generated, and the methods used for storage, transportation, and disposal; (5) Reporting their waste management activities to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible management of non-hazardous waste in Argentina, while minimizing the risks to human health and the environment.', 'This resolution sets out guidelines for the management and disposal of non-hazardous waste in Argentina. It establishes criteria for the classification of waste and provides guidelines for the storage, transportation, and disposal of non-hazardous waste. The resolution also includes provisions for the monitoring and reporting of waste management activities. Under this resolution companies have specific obligations related to the management and disposal of non-hazardous waste, including: (1) Properly classifying their waste according to the guidelines established in the resolution; (2) Storing and transporting their waste in a manner that prevents environmental contamination and protects human health; (3) Ensuring that their waste disposal methods comply with the legal requirements and do not pose a risk to the environment or public health; (4) Maintaining records and documentation related to their waste management activities, including the volume and type of waste generated, and the methods used for storage, transportation, and disposal; (5) Reporting their waste management activities to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible management of non-hazardous waste in Argentina, while minimizing the risks to human health and the environment.', 'This resolution sets out guidelines for the management and disposal of non-hazardous waste in Argentina. It establishes criteria for the classification of waste and provides guidelines for the storage, transportation, and disposal of non-hazardous waste. The resolution also includes provisions for the monitoring and reporting of waste management activities. Under this resolution companies have specific obligations related to the management and disposal of non-hazardous waste, including: (1) Properly classifying their waste according to the guidelines established in the resolution; (2) Storing and transporting their waste in a manner that prevents environmental contamination and protects human health; (3) Ensuring that their waste disposal methods comply with the legal requirements and do not pose a risk to the environment or public health; (4) Maintaining records and documentation related to their waste management activities, including the volume and type of waste generated, and the methods used for storage, transportation, and disposal; (5) Reporting their waste management activities to the appropriate regulatory authorities as required by law. Overall, the aim of these obligations is to promote the safe and responsible management of non-hazardous waste in Argentina, while minimizing the risks to human health and the environment.', 'Argentina', 'climate', 'in_force', '2002-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_44', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'argentina', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22ac15d3-546a-564c-ae81-a1685acd8f2f', 'Argentina Decree - Hydrocarbon pollution', 'Decree 962/98 - Hydrocarbon pollution', 'This decree creates the national system of preparation and fight against coastal, marine, fluvial and lake pollution by hydrocarbons and other noxious substances and potentially hazardous substances, which will be administered by the naval prefecture.', 'This decree creates the national system of preparation and fight against coastal, marine, fluvial and lake pollution by hydrocarbons and other noxious substances and potentially hazardous substances, which will be administered by the naval prefecture.', 'This decree creates the national system of preparation and fight against coastal, marine, fluvial and lake pollution by hydrocarbons and other noxious substances and potentially hazardous substances, which will be administered by the naval prefecture.', 'Argentina', 'climate', 'in_force', '1998-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_20', ARRAY['sdg13', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'argentina']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41e6935d-5df2-5c24-a782-170084051a5c', 'Argentina Decree Control of precursors and essential chemical substances', 'Decree 1095/1996 Control of precursors and essential chemical substances for the production of narcotic drugs', 'This Law establishes that the National Executive Power shall determine the substances that must be considered precursors and essential chemical products for the manufacture of narcotic drugs.', 'This Law establishes that the National Executive Power shall determine the substances that must be considered precursors and essential chemical products for the manufacture of narcotic drugs.', 'This Law establishes that the National Executive Power shall determine the substances that must be considered precursors and essential chemical products for the manufacture of narcotic drugs.', 'Argentina', 'climate', 'in_force', '1996-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_18', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'argentina', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2fd235f-6f21-5664-bd88-dcd410f02fe4', 'Argentina Mining Code (Modification)', 'Law 24.585 - Mining Code (Modification)', 'This law establishes a series of modifications to the Mining Code in order to carry out the protection of the environment and the conservation of the natural and cultural heritage that may be affected by mining activity. All natural and legal persons, public and private, centralized and decentralized entities and companies of the National, Provincial and Municipal State that develop mining activities are included within the regime of this Code.', 'This law establishes a series of modifications to the Mining Code in order to carry out the protection of the environment and the conservation of the natural and cultural heritage that may be affected by mining activity. All natural and legal persons, public and private, centralized and decentralized entities and companies of the National, Provincial and Municipal State that develop mining activities are included within the regime of this Code.', 'This law establishes a series of modifications to the Mining Code in order to carry out the protection of the environment and the conservation of the natural and cultural heritage that may be affected by mining activity. All natural and legal persons, public and private, centralized and decentralized entities and companies of the National, Provincial and Municipal State that develop mining activities are included within the regime of this Code.', 'Argentina', 'climate', 'in_force', '1995-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_24', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'argentina']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('27274dc4-376e-507e-b0ec-261bf2d76c50', 'Argentina Environmental Impact Assessment (EIA) Regulations', 'Environmental Impact Assessment (EIA) Regulations', 'Ley N° 24.585, also known as the Mining Activity and Environmental Impact Law, aims to regulate the environmental impact of mining activities in Argentina. The law emphasizes the protection of the environment and the conservation of cultural and natural heritage within the scope of mining operations. It establishes that miners have the right to exploit their resources freely, but they are required to adhere to environmental protection measures outlined in the law and related provisions.', 'Ley N° 24.585, also known as the Mining Activity and Environmental Impact Law, aims to regulate the environmental impact of mining activities in Argentina. The law emphasizes the protection of the environment and the conservation of cultural and natural heritage within the scope of mining operations. It establishes that miners have the right to exploit their resources freely, but they are required to adhere to environmental protection measures outlined in the law and related provisions.', 'Ley N° 24.585, also known as the Mining Activity and Environmental Impact Law, aims to regulate the environmental impact of mining activities in Argentina. The law emphasizes the protection of the environment and the conservation of cultural and natural heritage within the scope of mining operations. It establishes that miners have the right to exploit their resources freely, but they are required to adhere to environmental protection measures outlined in the law and related provisions.', 'Argentina', 'climate', 'in_force', '1995-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_7', ARRAY['argentina', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb159d27-b8a2-56c5-a559-5b8695ca9c39', 'Argentina Resolution - Fuels', 'Resolution 404/94 - Fuels', 'Resolution 404/94 impacts businesses involved in the production, importation, and commercialization of liquid fuels. The resolution establishes quality standards for liquid fuels, which businesses must adhere to in order to protect public health and the environment. Businesses involved in these activities are required to obtain licenses from regulatory authorities and comply with reporting and record-keeping requirements. Compliance with the standards is monitored through inspections of fuel production and storage facilities. Therefore, businesses must ensure that their operations meet the requirements of Resolution 404/94 to continue their activities in the country.', 'Resolution 404/94 impacts businesses involved in the production, importation, and commercialization of liquid fuels. The resolution establishes quality standards for liquid fuels, which businesses must adhere to in order to protect public health and the environment. Businesses involved in these activities are required to obtain licenses from regulatory authorities and comply with reporting and record-keeping requirements. Compliance with the standards is monitored through inspections of fuel production and storage facilities. Therefore, businesses must ensure that their operations meet the requirements of Resolution 404/94 to continue their activities in the country.', 'Resolution 404/94 impacts businesses involved in the production, importation, and commercialization of liquid fuels. The resolution establishes quality standards for liquid fuels, which businesses must adhere to in order to protect public health and the environment. Businesses involved in these activities are required to obtain licenses from regulatory authorities and comply with reporting and record-keeping requirements. Compliance with the standards is monitored through inspections of fuel production and storage facilities. Therefore, businesses must ensure that their operations meet the requirements of Resolution 404/94 to continue their activities in the country.', 'Argentina', 'climate', 'in_force', '1994-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_38', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'argentina', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eabaca3f-42fa-5c06-a7ac-d5d525e13717', 'Argentina Resolution - Hazardous Waste', 'Resolution 544/94 - Hazardous Waste', 'Resolution 544/94 was issued in Argentina in 1994 to regulate the generation, transportation, treatment, and disposal of hazardous waste. The resolution establishes the obligations of businesses regarding the management of hazardous waste, including the obligation to classify, segregate, store, transport, and dispose of hazardous waste in accordance with the established regulations. Businesses are required to obtain licenses from the relevant regulatory authorities to carry out these activities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 544/94 places significant obligations on businesses regarding the management of hazardous waste in Argentina, with the aim of protecting public health and the environment.', 'Resolution 544/94 was issued in Argentina in 1994 to regulate the generation, transportation, treatment, and disposal of hazardous waste. The resolution establishes the obligations of businesses regarding the management of hazardous waste, including the obligation to classify, segregate, store, transport, and dispose of hazardous waste in accordance with the established regulations. Businesses are required to obtain licenses from the relevant regulatory authorities to carry out these activities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 544/94 places significant obligations on businesses regarding the management of hazardous waste in Argentina, with the aim of protecting public health and the environment.', 'Resolution 544/94 was issued in Argentina in 1994 to regulate the generation, transportation, treatment, and disposal of hazardous waste. The resolution establishes the obligations of businesses regarding the management of hazardous waste, including the obligation to classify, segregate, store, transport, and dispose of hazardous waste in accordance with the established regulations. Businesses are required to obtain licenses from the relevant regulatory authorities to carry out these activities and comply with various reporting and record-keeping requirements. The resolution also establishes penalties for non-compliance with the regulations, including fines and potential legal action. Overall, Resolution 544/94 places significant obligations on businesses regarding the management of hazardous waste in Argentina, with the aim of protecting public health and the environment.', 'Argentina', 'climate', 'in_force', '1994-01-01'::date, 'Argentina', 'https://www.carrotsandsticks.org/policies/6_39', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'argentina', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('731bcf53-bc7c-5aec-aca4-aeda10aa7e26', 'Armenia Code of Corporate Governance', 'Code of Corporate Governance of the Republic of Armenia, 2010', 'The Code of Corporate Governance of the Republic of Armenia outlines principles and guidelines for good corporate governance practices in the country. The code is designed to enhance transparency, accountability, and responsibility among companies, and to promote investor confidence. The code covers various aspects of corporate governance, including the rights of shareholders, the role and responsibilities of the board of directors, the management of risk and internal controls, and the disclosure of information. It also establishes requirements for the composition and functioning of board committees, the remuneration of directors and executives, and the conduct of shareholder meetings. The code is applicable to all companies registered in Armenia, including state-owned enterprises, and sets out a voluntary compliance framework. Companies are encouraged to adopt the principles and recommendations of the code, and those that do so can be recognized as having good corporate governance practices. The code is also periodically reviewed and updated to reflect changes in corporate governance best practices.', 'The Code of Corporate Governance of the Republic of Armenia outlines principles and guidelines for good corporate governance practices in the country. The code is designed to enhance transparency, accountability, and responsibility among companies, and to promote investor confidence. The code covers various aspects of corporate governance, including the rights of shareholders, the role and responsibilities of the board of directors, the management of risk and internal controls, and the disclosure of information. It also establishes requirements for the composition and functioning of board committees, the remuneration of directors and executives, and the conduct of shareholder meetings. The code is applicable to all companies registered in Armenia, including state-owned enterprises, and sets out a voluntary compliance framework. Companies are encouraged to adopt the principles and recommendations of the code, and those that do so can be recognized as having good corporate governance practices. The code is also periodically reviewed and updated to reflect changes in corporate governance best practices.', 'The Code of Corporate Governance of the Republic of Armenia outlines principles and guidelines for good corporate governance practices in the country. The code is designed to enhance transparency, accountability, and responsibility among companies, and to promote investor confidence. The code covers various aspects of corporate governance, including the rights of shareholders, the role and responsibilities of the board of directors, the management of risk and internal controls, and the disclosure of information. It also establishes requirements for the composition and functioning of board committees, the remuneration of directors and executives, and the conduct of shareholder meetings. The code is applicable to all companies registered in Armenia, including state-owned enterprises, and sets out a voluntary compliance framework. Companies are encouraged to adopt the principles and recommendations of the code, and those that do so can be recognized as having good corporate governance practices. The code is also periodically reviewed and updated to reflect changes in corporate governance best practices.', 'Armenia', 'climate', 'in_force', '2010-01-01'::date, 'Armenia', 'https://www.carrotsandsticks.org/policies/7_1', ARRAY['regulations', 'sdg7', 'mandatory', 'armenia', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a18f5aa0-b1f9-555f-9982-c61c6d856031', 'ASEAN Taxonomy for Sustainable Finance (Version 1', 'ASEAN Taxonomy for Sustainable Finance (Version 1, 2021)', 'The ASEAN Taxonomy for Sustainable Finance provides a classification system to guide financial flows toward sustainable economic activities in ASEAN. Developed by the ASEAN Taxonomy Board (ATB), this framework supports climate transition strategies while being adaptable to diverse national policies. The taxonomy aims to attract sustainable investments, improve financing mechanisms, and align ASEAN economies with global sustainability goals.

Key provisions include:

Objectives & Scope:
A regional classification system for sustainable economic activities.
Applies to financial institutions, investors, and businesses across ASEAN.
Multi-Tiered Classification Approach:
Foundation Framework – A qualitative assessment applicable to all ASEAN nations.
Plus Standard – A science-based system with thresholds and performance criteria for green investments.
Environmental Objectives:
Climate Change Mitigation – Lowering greenhouse gas emissions.
Climate Change Adaptation – Strengthening resilience to climate risks.
Protection of Ecosystems & Biodiversity – Reducing pollution and deforestation.
Resource Resilience & Circular Economy – Promoting sustainable production and waste management.
Sector Prioritization & Classification:
Six priority sectors:
Agriculture, forestry, and fishing.
Manufacturing.
Electricity and energy supply.
Transportation.
Construction & real estate.
Water supply and waste management.
Activities categorized by impact using a traffic light system:
Green: Meets sustainability criteria.
Amber: Transitioning toward sustainability.
Red: Does not align with environmental goals.
Alignment with Global Standards:
The taxonomy is interoperable with other regional and global sustainability frameworks, including the EU Green Taxonomy and the Paris Agreement.
This taxonomy helps ASEAN countries attract green finance, reduce climate-related financial risks, and transition toward a low-carbon economy.', 'The ASEAN Taxonomy for Sustainable Finance provides a classification system to guide financial flows toward sustainable economic activities in ASEAN. Developed by the ASEAN Taxonomy Board (ATB), this framework supports climate transition strategies while being adaptable to diverse national policies. The taxonomy aims to attract sustainable investments, improve financing mechanisms, and align ASEAN economies with global sustainability goals.

