INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8decefae-a9f0-5953-a787-22458b2dc5d7', 'ASEAN Social Bond Standards', 'ASEAN Social Bond Standards', 'One of the key initiatives by the ACMF is the development of social asset classes in line with the growing importance of social finance in ASEAN. To support ASEAN’s sustainable development needs, the ACMF has developed the ASEAN Social Bond Standards (ASEAN SBS) to complement the ASEAN Green Bond Standards that were first introduced in November 2017. The ASEAN SBS intend to enhance transparency, consistency and uniformity of ASEAN Social Bonds which will also contribute to the development of a new asset class, reduce due diligence cost and help investors to make informed investment decisions.', 'One of the key initiatives by the ACMF is the development of social asset classes in line with the growing importance of social finance in ASEAN. To support ASEAN’s sustainable development needs, the ACMF has developed the ASEAN Social Bond Standards (ASEAN SBS) to complement the ASEAN Green Bond Standards that were first introduced in November 2017. The ASEAN SBS intend to enhance transparency, consistency and uniformity of ASEAN Social Bonds which will also contribute to the development of a new asset class, reduce due diligence cost and help investors to make informed investment decisions.', 'One of the key initiatives by the ACMF is the development of social asset classes in line with the growing importance of social finance in ASEAN. To support ASEAN’s sustainable development needs, the ACMF has developed the ASEAN Social Bond Standards (ASEAN SBS) to complement the ASEAN Green Bond Standards that were first introduced in November 2017. The ASEAN SBS intend to enhance transparency, consistency and uniformity of ASEAN Social Bonds which will also contribute to the development of a new asset class, reduce due diligence cost and help investors to make informed investment decisions.', 'ASEAN', 'climate', 'in_force', '2020-01-01'::date, 'Sustainable Finance Institute Asia', 'https://www.sfinstitute.asia/wp-content/uploads/2024/07/ASEAN-SDG-Bond-Toolkit.pdf', ARRAY['sdg14', 'asean', 'voluntary', 'sdg16', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73fbf395-52cc-59db-8f47-da69faf01e51', 'ASEAN Regional Multi-Stakeholder Forum: Responsible Business Conduct for Safe', 'Regional Multi-Stakeholder Forum: Responsible Business Conduct for Safe Labour Migration in ASEAN', 'The Forum acknowledged the complementarity and mutual reinforcement of ASEAN frameworks (notably the ASEAN Consensus on the Protection and Promotion of the Rights of Migrant Workers (ASEAN Consensus), ASEAN Convention Against Trafficking in Persons Especially Women and Children (ACTIP), and ASEAN Guidelines for Corporate Social Responsibility on Labour) and global agendas of the Sustainable Development Goals and the Global Compact for Safe, Orderly and Regular Migration in promoting responsible business conduct for safe labour migration in the region. The Forum emphasized the importance of ensuring syncronisation of actions taken at local and national levels with ASEAN Member States’ commitments, both legally and non-legally binding, at regional and international levels.', 'The Forum acknowledged the complementarity and mutual reinforcement of ASEAN frameworks (notably the ASEAN Consensus on the Protection and Promotion of the Rights of Migrant Workers (ASEAN Consensus), ASEAN Convention Against Trafficking in Persons Especially Women and Children (ACTIP), and ASEAN Guidelines for Corporate Social Responsibility on Labour) and global agendas of the Sustainable Development Goals and the Global Compact for Safe, Orderly and Regular Migration in promoting responsible business conduct for safe labour migration in the region. The Forum emphasized the importance of ensuring syncronisation of actions taken at local and national levels with ASEAN Member States’ commitments, both legally and non-legally binding, at regional and international levels.', 'The Forum acknowledged the complementarity and mutual reinforcement of ASEAN frameworks (notably the ASEAN Consensus on the Protection and Promotion of the Rights of Migrant Workers (ASEAN Consensus), ASEAN Convention Against Trafficking in Persons Especially Women and Children (ACTIP), and ASEAN Guidelines for Corporate Social Responsibility on Labour) and global agendas of the Sustainable Development Goals and the Global Compact for Safe, Orderly and Regular Migration in promoting responsible business conduct for safe labour migration in the region. The Forum emphasized the importance of ensuring syncronisation of actions taken at local and national levels with ASEAN Member States’ commitments, both legally and non-legally binding, at regional and international levels.', 'ASEAN', 'climate', 'in_force', '2018-01-01'::date, 'ASEAN CSR Network', 'http://www.asean-csr-network.org/c/news-a-resources/csr-news-from-around-asean/1289-recommendations-of-the-regional-multi-stakeholder-forum-responsible-business-conduct-for-safe-labour-migration-in-asean', ARRAY['sdg8', 'sdg14', 'asean', 'regulations', 'sdg17', 'sdg5', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
